306. # Download DWARF symbols from the Microsoft symbol server using a Mach-O UUID
307. function Get-DebugSymbols([string]$uuid, [string]$cacheDir, [string]$serverUrl) {
308.     $dwarfFile = Join-Path $cacheDir "$uuid.dwarf"
309. 
310.     if (Test-Path $dwarfFile) {
311.         Write-Verbose "Using cached symbols for UUID $uuid"
312.         return $dwarfFile
313.     }
314. 
315.     $url = "$serverUrl/_.dwarf/mach-uuid-sym-$uuid/_.dwarf"
316.     Write-Verbose "Downloading symbols from $url"
317. 
318.     $savedProgressPreference = $ProgressPreference
319.     try {
320.         $ProgressPreference = 'SilentlyContinue'
321.         Invoke-WebRequest -Uri $url -OutFile $dwarfFile -TimeoutSec 120
322. 
323.         # Verify the download is a Mach-O file (64-bit LE magic: CF FA ED FE)
324.         $stream = [System.IO.File]::OpenRead($dwarfFile)
325.         try {
326.             $header = [byte[]]::new(4)
327.             $bytesRead = $stream.Read($header, 0, 4)
328.         }
329.         finally {
330.             $stream.Close()
331.         }
332.         if ($bytesRead -ge 4 -and $header[0] -eq 0xCF -and $header[1] -eq 0xFA -and $header[2] -eq 0xED -and $header[3] -eq 0xFE) {
333.             $size = (Get-Item $dwarfFile).Length
334.             Write-Verbose "Downloaded $([math]::Round($size / 1MB, 1)) MB symbols for UUID $uuid"
335.             return $dwarfFile
336.         }
337.         else {
338.             Write-Warning "Downloaded file for UUID $uuid is not a valid Mach-O file (symbols may not be published)"
339.             Remove-Item $dwarfFile -ErrorAction SilentlyContinue
340.             return $null
341.         }
342.     }
343.     catch {
344.         Write-Warning "Failed to download symbols for UUID $uuid`: $_"
345.         Remove-Item $dwarfFile -ErrorAction SilentlyContinue
346.         return $null
347.     }
348.     finally {
349.         $ProgressPreference = $savedProgressPreference
350.     }
351. }
