400. # Symbolicate a batch of addresses for one image using atos
401. function Resolve-Frames([string]$dsymPath, [string]$arch, [uint64]$loadAddress, [uint64[]]$addresses, [string]$atosPath) {
402.     $loadHex = '0x{0:x}' -f $loadAddress
403.     $addrArgs = $addresses | ForEach-Object { '0x{0:x}' -f $_ }
404. 
405.     try {
406.         $output = & $atosPath -arch $arch -o $dsymPath -l $loadHex @addrArgs 2>$null
407.         if ($LASTEXITCODE -ne 0 -or -not $output) { return @() }
408. 
409.         $results = [System.Collections.Generic.List[object]]::new()
410.         $lines = @($output)
411.         for ($i = 0; $i -lt [Math]::Min($lines.Count, $addresses.Count); $i++) {
412.             $line = $lines[$i].Trim()
413.             # atos returns "0xADDRESS" for unresolved frames
414.             if ($line -match '^0x[0-9a-fA-F]+$') {
415.                 $results.Add($null)
416.             }
417.             else {
418.                 # Parse: "functionName (in libraryName) (sourcefile:line)"
419.                 $funcName = $line
420.                 $source = $null
421.                 if ($line -match '^(.+?)\s+\(in\s+.+?\)\s+\((.+)\)$') {
422.                     $funcName = $Matches[1]
423.                     $source = $Matches[2]
424.                     # Strip CI build agent path prefixes
425.                     $source = $source -replace '^/__w/\d+/s/', ''
426.                 }
427.                 elseif ($line -match '^(.+?)\s+\(in\s+.+?\)$') {
428.                     $funcName = $Matches[1]
429.                 }
430.                 $results.Add([PSCustomObject]@{
431.                     Function = $funcName
432.                     Source   = $source
433.                 })
434.             }
435.         }
436.         return $results.ToArray()
437.     }
438.     catch {
439.         Write-Verbose "atos failed: $_"
440.         return @()
441.     }
442. }
