413.             # atos returns "0xADDRESS" for unresolved frames
414.             if ($line -match '^0x[0-9a-fA-F]+$') {
415.                 $results.Add($null)
416.             }
417.             else {
418.                 # Parse: "functionName (in libraryName) (sourcefile:line)"
419.                 $funcName = $line
